local function notify(t)
    pcall(function()
        StarterGui:SetCore("SendNotification",{Title="ShiBu FPS Boost",Text=t,Duration=3})
    end)
end

local function setCap(v)
    currentCap=v
    pcall(function()
        if setfpscap then
            setfpscap(v=="UNCAP" and 999 or v)
        end
    end)
end

local function b64decode(data)
    local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data=data:gsub('[^'..b..'=]','')
    return (data:gsub('.',function(x)
        if x=='=' then return '' end
        local r,f='',(b:find(x,1,true)-1)
        for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
        if #x~=8 then return '' end
        local c=0
        for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
        return string.char(c)
    end))
end

local function embeddedLogo()
    local asset=nil
    pcall(function()
        if writefile and (getcustomasset or getsynasset) then
            if makefolder then pcall(function() makefolder("ShiBu") end) end
            local p="ShiBu/ShiBu_FPS_Logo.png"
            if not isfile or not isfile(p) then writefile(p,b64decode(LOGO_B64)) end
            asset=(getcustomasset and getcustomasset(p)) or (getsynasset and getsynasset(p))
        end
    end)
    return asset
end

local LOGO=embeddedLogo()

local function optimize(v,mode)
    pcall(function()
        if v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Beam")
        or v:IsA("Smoke") or v:IsA("Fire") or v:IsA("Sparkles") then
            v.Enabled=false
        elseif v:IsA("BasePart") then
            v.CastShadow=false
            v.Reflectance=0
            if mode~="Light" then v.Material=Enum.Material.SmoothPlastic end
        elseif (v:IsA("Decal") or v:IsA("Texture")) and mode=="Ultra" then
            v.Transparency=1
        elseif v:IsA("PostEffect") then
            v.Enabled=false
        end
    end)
end

local function applyMode(mode)
    currentMode=mode
    pcall(function() settings().Rendering.QualityLevel=Enum.QualityLevel.Level01 end)
    Lighting.GlobalShadows=false
    Lighting.FogEnd=1e9
    if mode~="Light" then
        Lighting.EnvironmentDiffuseScale=0
        Lighting.EnvironmentSpecularScale=0
    end
    for _,v in ipairs(game:GetDescendants()) do optimize(v,mode) end
    if addedConn then addedConn:Disconnect() end
    addedConn=game.DescendantAdded:Connect(function(v) task.defer(optimize,v,currentMode) end)
    notify(mode.." mode enabled")
end

local function autoDetect(done)
    if autoBusy then return end
    autoBusy=true
    setCap("UNCAP")
    local samples={}
    local start=os.clock()
    local c
    c=RunService.RenderStepped:Connect(function(dt)
        if dt>0 then table.insert(samples,math.clamp(1/dt,1,240)) end
        if os.clock()-start>=3 then
            c:Disconnect()
            table.sort(samples)
            local fps=60
            if #samples>0 then fps=samples[math.max(1,math.floor(#samples*0.75))] end
            local cap=fps>=105 and 120 or (fps>=78 and 90 or 60)
            setCap(cap)
            autoBusy=false
            if done then done(cap,math.floor(fps+0.5)) end
            notify("AUTO selected "..cap.." FPS")
        end
    end)
end

